<script setup>
defineProps({providers:{type:Array,default:()=>[]},prompts:{type:Array,default:()=>[]},runtime:{type:Object,default:null},providerDraft:{type:Object,required:true},providerEditingId:{type:String,default:''},promptDraft:{type:Object,required:true},error:{type:String,default:''},loading:Boolean,busy:Boolean})
const emit=defineEmits(['refresh','back','save-provider','edit-provider','cancel-provider','patch-provider','health','save-prompt','activate-prompt'])
const healthLabels={healthy:'健康',unhealthy:'不可用',unconfigured:'缺少密钥',disabled:'已停用',unchecked:'未检查'}
function fmtTime(value){return value?String(value).slice(0,19).replace('T',' '):'—'}
</script>
<template>
  <main class="admin model-ops-page">
    <header><div><span class="eyebrow">MODEL OPERATIONS</span><h1>模型与提示词</h1></div><div class="head-actions"><button class="ghost" :disabled="loading" @click="emit('refresh')">刷新</button><button class="run" @click="emit('back')">← 返回查询</button></div></header>
    <div v-if="error" class="error">{{error}}</div>
    <section class="model-runtime-band"><div><span>运行来源</span><b>{{runtime?.source==='tenant'?'租户配置':'环境默认'}}</b></div><div><span>当前模型</span><b>{{runtime?.model||'—'}}</b></div><div><span>提示词版本</span><b>{{runtime?.prompt_version||'—'}}</b></div><div><span>密钥状态</span><b :class="runtime?.credential_configured?'state-ok':'state-warn'">{{runtime?.credential_configured?'已配置':'未配置'}}</b></div></section>
    <div class="model-ops-grid">
      <section class="card provider-form"><div class="semantic-card-head"><h3>{{providerEditingId?'编辑提供商':'注册提供商'}}</h3><button v-if="providerEditingId" class="ghost" @click="emit('cancel-provider')">取消编辑</button></div><form class="model-form" @submit.prevent="emit('save-provider')"><label>名称<input v-model="providerDraft.name" maxlength="120" required></label><label>适配器<select v-model="providerDraft.adapter"><option value="direct">OpenAI 兼容</option><option value="langchain">LangChain</option></select></label><label class="wide">接口地址<input v-model="providerDraft.base_url" maxlength="500" type="url" required></label><label>模型标识<input v-model="providerDraft.model" maxlength="160" required></label><label>密钥环境变量<input v-model="providerDraft.api_key_env" maxlength="128" pattern="[A-Z][A-Z0-9_]+" required></label><label class="check"><input v-model="providerDraft.enabled" type="checkbox">启用</label><label class="check"><input v-model="providerDraft.is_default" type="checkbox">设为默认</label><button class="run" type="submit" :disabled="busy">{{busy?'保存中…':providerEditingId?'保存修改':'注册提供商'}}</button></form></section>
      <section class="card prompt-form"><h3>新增提示词版本</h3><form class="model-form" @submit.prevent="emit('save-prompt')"><label>模板名称<input v-model="promptDraft.name" maxlength="64" pattern="[A-Za-z0-9_.-]+" required></label><label class="wide">系统提示词<textarea v-model="promptDraft.system_prompt" maxlength="8000" rows="9" required></textarea></label><label class="check"><input v-model="promptDraft.activate" type="checkbox">保存后激活</label><button class="run" type="submit" :disabled="busy">{{busy?'保存中…':'创建版本'}}</button></form></section>
    </div>
    <section class="model-ops-section"><div class="model-section-head"><h2>模型提供商</h2><span>{{providers.length}} 个</span></div><div v-if="loading" class="model-empty">正在加载…</div><div v-else-if="!providers.length" class="model-empty">暂无租户级模型提供商。</div><div v-else class="provider-list"><article v-for="provider in providers" :key="provider.id" class="provider-row"><div class="provider-main"><div><strong>{{provider.name}}</strong><span v-if="provider.is_default" class="model-badge">默认</span><span class="health-state" :class="provider.health_status">{{healthLabels[provider.health_status]||provider.health_status}}</span></div><code>{{provider.model}} · {{provider.adapter}} · {{provider.base_url}}</code><small>{{provider.api_key_env}} · {{provider.credential_configured?'密钥已注入':'密钥未注入'}}<template v-if="provider.last_checked_at"> · {{fmtTime(provider.last_checked_at)}} · {{provider.last_latency_ms}} ms</template></small></div><div class="provider-actions"><button class="ghost" :disabled="busy" @click="emit('health',provider)">检查</button><button class="ghost" :disabled="busy" @click="emit('edit-provider',provider)">编辑</button><button v-if="!provider.is_default" class="ghost" :disabled="busy||!provider.enabled" @click="emit('patch-provider',provider,{is_default:true})">设为默认</button><button class="ghost" :disabled="busy" @click="emit('patch-provider',provider,{enabled:!provider.enabled})">{{provider.enabled?'停用':'启用'}}</button></div></article></div></section>
    <section class="model-ops-section"><div class="model-section-head"><h2>提示词版本</h2><span>{{prompts.length}} 个</span></div><div v-if="!prompts.length" class="model-empty">当前使用内置安全提示词。</div><div v-else class="prompt-list"><article v-for="prompt in prompts" :key="prompt.id" class="prompt-row"><div><strong>{{prompt.name}} v{{prompt.version}}</strong><span v-if="prompt.active" class="model-badge">已激活</span><small>{{fmtTime(prompt.created_at)}} · {{prompt.owner_id||'system'}}</small><p>{{prompt.system_prompt}}</p></div><button v-if="!prompt.active" class="ghost" :disabled="busy" @click="emit('activate-prompt',prompt)">激活此版本</button></article></div></section>
  </main>
</template>
